package io.github.diodeme.ji.provider.http;

import java.time.Duration;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionStage;

/** Injectable retry delay boundary for deterministic provider contract tests. */
@FunctionalInterface
public interface RetryScheduler {
    CompletionStage<Void> delay(Duration duration);

    static RetryScheduler system() {
        return duration -> CompletableFuture.runAsync(
                () -> {}, CompletableFuture.delayedExecutor(duration.toMillis(), java.util.concurrent.TimeUnit.MILLISECONDS));
    }
}
